SELECT DISTINCT t.user_selection_id, t.user_id, t.user_name, t.nick_name, t.pattern_combo_code, t.career_titles, t.env_titles, t.created_at FROM (
) t
and t.user_id = #{userId} and t.user_name like concat('%', #{userName}, '%') and t.pattern_combo_code = #{patternComboCode} and EXISTS ( SELECT 1 FROM xycc_pattern_combo pc2 LEFT JOIN xycc_pattern_combo_career pcc2 ON pc2.pattern_combo_id = pcc2.combo_id LEFT JOIN xycc_career c2 ON pcc2.career_id = c2.career_id WHERE pc2.code = t.pattern_combo_code AND c2.title like concat('%', #{careerTitles}, '%') ) and EXISTS ( SELECT 1 FROM xycc_pattern_combo pc2 LEFT JOIN xycc_pattern_combo_env pce2 ON pc2.pattern_combo_id = pce2.combo_id LEFT JOIN xycc_work_env e2 ON pce2.env_id = e2.work_env_id WHERE pc2.code = t.pattern_combo_code AND e2.title like concat('%', #{envTitles}, '%') ) and t.created_at between #{params.beginCreatedAt} and #{params.endCreatedAt}

